import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"蒙","description":"東坡易傳 - 蒙","frontmatter":{"title":"蒙","description":"東坡易傳 - 蒙"},"headers":[],"relativePath":"classics/dongpo/005.md","filePath":"classics/dongpo/005.md"}'),o={name:"classics/dongpo/005.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="蒙" tabindex="-1">蒙 <a class="header-anchor" href="#蒙" aria-label="Permalink to “蒙”">​</a></h1><p>“蒙”：亨。匪我求童蒙，童蒙求我。初筮告，再三瀆，瀆則不告。利貞。</p><p>《彖》曰：“蒙”，山下有險，險而止，“蒙”。“蒙，亨”，以亨行時中也。“匪我求童蒙，童蒙求我”，志應也。“初筮告”，以剛中也；“再三瀆，瀆則不告”，瀆蒙也。蒙以養正，聖功也。</p><p>“蒙”者，有蔽於物而已，其中固自有正也。蔽雖甚，終不能沒其正，將戰於內以求自達，因其欲達而一發之，迎其正心，彼將沛然而自得焉。苟不待其欲達而強發之，一發不達，以至於再三，雖有得，非其正矣。故曰：“匪我求童蒙，童蒙求我。”彼將內患其蔽，即我而求達，我何為求之？夫患蔽不深，則求達不力；求達不力，則正心不勝；正心不勝，則我雖告之，彼無自入焉。故初筮告者，因其欲達而一發之也。“再三瀆，瀆則不告”者，發之不待其欲達①，而至於再三也。“蒙，亨，以亨行”者，言其一通而不復塞也。夫能使之一通而不復塞者，豈非時其中之，欲達而一發之乎？故曰“時中”也。聖人之於“蒙”也，時其可發而發之，不可則置之，所以養其正心而待其自勝也，此聖人之功也。</p><p>【校注】 ①達，《蘇氏易傳》作“進”，誤。</p><p>《象》曰：山下出泉，“蒙”；君子以果行育德。</p><p>“果行”者，求發也。“育德”者，不發以養正也。</p><p>初六：發矇，利用刑人，用說桎梏；以往，吝。象曰：“利用刑人”，以正法也。</p><p>所以“發矇”者，用於未發，既發則無用。既發而用者，瀆蒙也。“桎梏”者，用於未刑，既刑則說。既刑而不說者，瀆刑也。發矇者慎其初，不可使至瀆。故於初雲爾。</p><p>九二：包蒙，吉。納婦，吉。子克家。象曰：“子克家”，剛柔節也。</p><p>童蒙，若無能為也。然而容之則足以為助，拒之則所喪多矣。明之不可以無蒙，猶子之不可以無婦，子而無婦，不能家矣。</p><p>六三：勿用取女，見金夫，不有躬，無攸利。象曰：“勿用取女”，行不順也。</p><p>王弼曰：“童蒙之時，陰求於陽，”“上不求三而三求於上，女先求男者也。女之為體，正行以待命者也，見剛夫而求之，故曰‘不有躬’也。施之於女，行不順”矣。</p><p>六四：困蒙，吝。象曰：“困蒙”之吝，獨遠實也。</p><p>實，陽也。</p><p>六五：童蒙，吉。象曰：“童蒙”之吉，順以巽也。</p><p>六五之位尊矣，恐其不安於童蒙之分，而自強於明，故教之曰：“童蒙，吉”。</p><p>上九：擊蒙，不利為寇，利禦寇。象曰：利用“禦寇”，上下順也。</p><p>以剛自高，而下臨弱，故至於用擊也。發矇不得其道，而至於用擊，過矣。故有以戒之。王弼曰：“為之捍禦，則物鹹附之。若欲取之，則物鹹叛矣。”</p>',19)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
